insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:17-088a330fde','aux-ayto-mad',17,'El Comité de Seguridad y Salud se reunirá:','["Trimestralmente y siempre que lo solicite alguna de las representaciones", "Semestralmente", "Mensualmente y cuando lo convoque el empresario"]'::jsonb,0,'Art. 38.3 Ley 31/1995','Según el art. 38.3, se reúne trimestralmente y siempre que lo solicite alguna de las representaciones; adopta sus propias normas de funcionamiento.',null),
('aux-ayto-mad:17-30c1e7f3d8','aux-ayto-mad',17,'En las empresas que no cuenten con Comité de Seguridad y Salud por no alcanzar el número mínimo de trabajadores, sus competencias las ejercen:','["El Comité de Empresa", "Los Delegados de Prevención", "El empresario"]'::jsonb,1,'Art. 36.1 Ley 31/1995','Así lo establece el último párrafo del art. 36.1.',null),
('aux-ayto-mad:17-78eb1d7865','aux-ayto-mad',17,'Entre las facultades del Comité de Seguridad y Salud figura:','["Aprobar el presupuesto de la empresa", "Imponer sanciones a los trabajadores que incumplan las medidas de prevención", "Conocer e informar la memoria y programación anual de servicios de prevención"]'::jsonb,2,'Art. 39.2 d) Ley 31/1995','Es una de las facultades del art. 39.2.',null),
('aux-ayto-mad:17-1bf40ba2a5','aux-ayto-mad',17,'En el ámbito de las Administraciones públicas se constituirá, con carácter general:','["Un Comité de Seguridad y Salud por cada centro de trabajo", "Un Comité para el personal funcionario y otro para el laboral", "Un único Comité de Seguridad y Salud en el ámbito de los órganos de representación del personal"]'::jsonb,2,'Art. 34.3 d) Ley 31/1995','Lo integran los Delegados de Prevención de ese ámbito, para personal funcionario, estatutario y laboral, y representantes de la Administración en número no superior al de Delegados.',null),
('aux-ayto-mad:17-22798d532e','aux-ayto-mad',17,'Los trabajadores y sus representantes pueden recurrir a la Inspección de Trabajo y Seguridad Social si consideran que las medidas del empresario:','["Son más costosas de lo necesario para la empresa", "No son suficientes para garantizar la seguridad y la salud en el trabajo", "Afectan a su retribución"]'::jsonb,1,'Art. 40.1 Ley 31/1995','Así lo establece el art. 40.1.',null),
('aux-ayto-mad:17-475aa438da','aux-ayto-mad',17,'Los Delegados de Prevención pueden presentarse en el lugar de los hechos para conocer las circunstancias de los daños producidos en la salud de los trabajadores:','["Solo dentro de su jornada laboral", "Solo con autorización previa del empresario", "Aun fuera de su jornada laboral"]'::jsonb,2,'Art. 36.2 c) Ley 31/1995','Según el art. 36.2 c), pueden presentarse aún fuera de su jornada laboral.',null),
('aux-ayto-mad:18-fd420fca27','aux-ayto-mad',18,'Según la Ley 39/2015, cada Administración dispondrá de:','["Un Registro Electrónico General", "Un registro único estatal", "Un registro en papel por cada órgano"]'::jsonb,0,'Art. 16.1 Ley 39/2015','Cada Administración dispondrá de un Registro Electrónico General.',null),
('aux-ayto-mad:18-cb0c94d962','aux-ayto-mad',18,'¿Dónde NO se pueden presentar documentos dirigidos a las Administraciones según el art. 16.4 de la Ley 39/2015?','["En las oficinas de asistencia en materia de registros", "En las representaciones diplomáticas u oficinas consulares", "En cualquier comercio colaborador"]'::jsonb,2,'Art. 16.4 Ley 39/2015','Se pueden presentar en los registros electrónicos, en Correos, en representaciones diplomáticas u oficinas consulares, en las oficinas de asistencia en materia de registros y donde establezcan las disposiciones vigentes.',null),
('aux-ayto-mad:18-7e745c2a9a','aux-ayto-mad',18,'Cada Administración debe mantener, para los documentos electrónicos de procedimientos finalizados:','["Un archivo electrónico único", "Un archivo por cada funcionario", "Un archivo en papel"]'::jsonb,0,'Art. 17.1 Ley 39/2015','Debe mantener un archivo electrónico único de los documentos electrónicos de procedimientos finalizados.',null),
('aux-ayto-mad:18-8e34628169','aux-ayto-mad',18,'Tras presentar un documento en el registro electrónico se emite automáticamente:','["Una resolución de admisión a trámite firmada por el órgano competente para resolver, con indicación del plazo máximo para hacerlo", "Un recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada", "Un justificante sin fecha, que se completa el primer día hábil siguiente"]'::jsonb,1,'Art. 16.3 Ley 39/2015','El registro emite automáticamente un recibo consistente en una copia autenticada del documento, con fecha, hora y número de entrada.',null),
('aux-ayto-mad:18-55af533af5','aux-ayto-mad',18,'Una vez digitalizados por la oficina de asistencia, los documentos originales presentados presencialmente:','["Se remiten siempre al archivo central de la consejería que tramita el expediente, para su custodia hasta que se dicte la resolución", "Se devuelven al interesado, salvo que una norma determine su custodia por la Administración", "Se destruyen una vez transcurridos quince días hábiles desde su presentación"]'::jsonb,1,'Art. 16.5 Ley 39/2015','Los originales se devuelven al interesado, sin perjuicio de los supuestos en que la norma determine la custodia por la Administración.',null),
('aux-ayto-mad:18-340b1b2b71','aux-ayto-mad',18,'Las Administraciones deben hacer pública y mantener actualizada:','["Una relación de las oficinas en las que se presta asistencia para la presentación electrónica de documentos", "La lista de los funcionarios que digitalizan documentos en cada oficina", "La lista de los interesados que han presentado documentos en papel durante el último año"]'::jsonb,0,'Art. 16.7 Ley 39/2015','El art. 16.7 obliga a publicar y actualizar la relación de oficinas de asistencia en materia de registros.',null),
('aux-ayto-mad:18-d1fa877de6','aux-ayto-mad',18,'Los documentos electrónicos deben conservarse en un formato que permita garantizar:','["Su integridad mientras el procedimiento esté en tramitación, pero no después", "Su consulta durante los cinco años siguientes a la finalización del procedimiento, plazo tras el cual pueden eliminarse sin más trámite", "Su autenticidad, integridad y conservación, y su consulta con independencia del tiempo transcurrido"]'::jsonb,2,'Art. 17.2 Ley 39/2015','El art. 17.2 exige un formato que garantice autenticidad, integridad y conservación, y la consulta sin importar el tiempo transcurrido.',null),
('aux-ayto-mad:18-e1c957e578','aux-ayto-mad',18,'Los asientos en el registro electrónico se anotan:','["Respetando el orden temporal de recepción o salida de los documentos", "Agrupados por procedimientos administrativos al final de cada jornada de trabajo", "Por orden de importancia del asunto, según decida el responsable del registro"]'::jsonb,0,'Art. 16.2 Ley 39/2015','Indican la fecha del día en que se producen.',null),
('aux-ayto-mad:18-fa1f4000d7','aux-ayto-mad',18,'Los documentos que los interesados presenten en papel en las oficinas de asistencia en materia de registros:','["Se destruyen tras su presentación para evitar duplicidades", "Se remiten por valija a la unidad tramitadora, que los conserva en papel junto con el resto del expediente", "Se digitalizan para incorporarlos al expediente electrónico y se devuelven los originales al interesado"]'::jsonb,2,'Art. 16.5 Ley 39/2015','Salvo que la norma determine la custodia de los documentos por la Administración o que se trate de objetos o documentos en un soporte específico no susceptibles de digitalización.',null),
('aux-ayto-mad:18-8705e4ddb7','aux-ayto-mad',18,'Cada Administración debe mantener un archivo electrónico único de:','["Las resoluciones judiciales que le afecten", "Los expedientes de personal de todos sus funcionarios y del personal laboral a su servicio", "Los documentos electrónicos que correspondan a procedimientos finalizados"]'::jsonb,2,'Art. 17.1 Ley 39/2015','Los documentos se conservan en un formato que permita garantizar su autenticidad, integridad y conservación.',null),
('aux-ayto-mad:18-261edadf9e','aux-ayto-mad',18,'¿A través de qué dirección se accede al Registro Electrónico General del Ayuntamiento de Madrid?','["A través del portal institucional «madrid.es»", "A través del Punto de Acceso General de la Administración del Estado", "A través de la Sede Electrónica «sede.madrid.es»"]'::jsonb,2,'Art. 36.2 OACAE','El acceso al Registro Electrónico General se realiza a través de la Sede Electrónica, identificándose previamente con alguno de los medios aceptados.',null),
('aux-ayto-mad:18-b6717a1391','aux-ayto-mad',18,'¿Qué días y horas se pueden presentar documentos en el Registro Electrónico General del Ayuntamiento de Madrid?','["Todos los días del año, de 8:00 a 20:00 horas", "Los días hábiles durante las 24 horas", "Todos los días del año durante las 24 horas"]'::jsonb,2,'Art. 36.3 OACAE','En el Registro Electrónico General se pueden presentar documentos todos los días del año durante las 24 horas.',null),
('aux-ayto-mad:18-45f2131cd6','aux-ayto-mad',18,'¿Qué fecha y hora oficial indica el Registro Electrónico General del Ayuntamiento de Madrid?','["La misma que figure en la Sede Electrónica", "La del Real Instituto y Observatorio de la Armada", "La del servidor de la oficina de registro de entrada"]'::jsonb,0,'Art. 36.3 OACAE','El Registro indicará la fecha y hora oficial, que será la misma que figure en la Sede Electrónica del Ayuntamiento.',null),
('aux-ayto-mad:18-49120581a8','aux-ayto-mad',18,'¿Dónde se publican las disposiciones de creación de los registros electrónicos del Ayuntamiento de Madrid?','["En el Boletín Oficial de la Comunidad de Madrid", "En el Boletín Oficial del Estado", "En el Boletín Oficial del Ayuntamiento de Madrid"]'::jsonb,2,'Art. 36.4 OACAE','Las disposiciones de creación de los registros electrónicos se publican en el BOAM y su texto íntegro debe estar en la Sede Electrónica.',null),
('aux-ayto-mad:18-386bf526cd','aux-ayto-mad',18,'¿Qué complementa al Registro Electrónico General del Ayuntamiento de Madrid?','["Las oficinas de asistencia en materia de registro", "El Registro Electrónico General de Apoderamientos", "Los registros auxiliares de cada Área de Gobierno"]'::jsonb,0,'Art. 36.6 OACAE','El Registro Electrónico General será complementado por las oficinas de asistencia en materia de registro.',null),
('aux-ayto-mad:18-e5b10dfbeb','aux-ayto-mad',18,'¿En qué orden se anotan los asientos en el Registro Electrónico General?','["Por orden alfabético del órgano destinatario", "Agrupados por procedimiento administrativo", "Respetando el orden temporal de recepción o salida de los documentos"]'::jsonb,2,'Art. 37.2 OACAE','Los asientos se anotan respetando el orden temporal de recepción o salida e indican la fecha del día en que se producen.',null),
('aux-ayto-mad:18-a4ad265acf','aux-ayto-mad',18,'¿Qué determina, según el recibo del Registro Electrónico General, el inicio del cómputo de plazos?','["La fecha de entrada en el órgano competente", "La fecha y hora de presentación", "La fecha de emisión del recibo en papel"]'::jsonb,1,'Art. 37.5 b) OACAE','El recibo contiene la fecha y hora de presentación, que determinará el inicio del cómputo de plazos.',null),
('aux-ayto-mad:18-0209ef5467','aux-ayto-mad',18,'¿Qué puede hacer el Registro Electrónico General con documentos electrónicos que contengan código malicioso?','["Rechazarlos, informando al remitente de los motivos", "Admitirlos y aislarlos hasta que se subsanen", "Destruirlos sin informar al remitente"]'::jsonb,0,'Art. 37.7 OACAE','Se pueden rechazar los documentos con código malicioso, informando al remitente de los motivos y, si es posible, de cómo subsanarlo.',null),
('aux-ayto-mad:18-3e8caa00f9','aux-ayto-mad',18,'¿Qué naturaleza tienen las oficinas de asistencia en materia de registro del Ayuntamiento de Madrid?','["La de unidad administrativa sin rango de órgano", "La de organismo autónomo", "La de órgano administrativo"]'::jsonb,2,'Art. 39.3 OACAE','Las oficinas de asistencia en materia de registro tienen naturaleza de órgano administrativo, según el art. 5 de la Ley 40/2015.',null),
('aux-ayto-mad:18-9b72aff771','aux-ayto-mad',18,'¿Cómo se crean, modifican o suprimen las oficinas de asistencia en materia de registro del Ayuntamiento de Madrid?','["Por decreto del alcalde, sin necesidad de publicación", "Por acuerdo del Pleno publicado en el BOCM", "Por resolución del órgano competente publicada en el BOAM"]'::jsonb,2,'Art. 39.4 OACAE','Se crean, modifican o suprimen mediante resolución del órgano competente que debe publicarse en el Boletín Oficial del Ayuntamiento de Madrid.',null),
('aux-ayto-mad:18-a2afa394de','aux-ayto-mad',18,'En la recepción y digitalización de documentos por las oficinas de asistencia en materia de registro, ¿qué se hace con carácter general con los originales?','["Se devuelven a la persona interesada", "Se custodian en el archivo de la oficina", "Se remiten al órgano destinatario"]'::jsonb,0,'Art. 40.1 a) OACAE','Se devuelven los originales a la persona interesada, salvo que la norma determine su custodia o no sean susceptibles de digitalización.',null),
('aux-ayto-mad:18-2b1f852141','aux-ayto-mad',18,'¿Qué calendario se aplica a efectos del cómputo de plazos en los registros electrónicos del Ayuntamiento de Madrid?','["El calendario oficial de días inhábiles publicado en su Sede Electrónica", "El calendario laboral de la Comunidad de Madrid", "El calendario de días inhábiles del Estado publicado en el BOE"]'::jsonb,0,'Art. 41.1 OACAE','El calendario de días inhábiles publicado en la Sede Electrónica es el único que se aplica para el cómputo de plazos en los registros electrónicos.',null),
('aux-ayto-mad:18-cf0053adb5','aux-ayto-mad',18,'Si un interesado presenta un documento en el Registro Electrónico General en un día inhábil, ¿cuándo se entiende presentado a efectos de plazos en días hábiles?','["En la primera hora del primer día hábil siguiente", "A la misma hora del primer día hábil siguiente", "En el momento efectivo de la presentación"]'::jsonb,0,'Art. 41.3 OACAE','Salvo norma que permita la recepción en día inhábil, se entiende realizada en la primera hora del primer día hábil siguiente.',null),
('aux-ayto-mad:18-d968454ab2','aux-ayto-mad',18,'¿Qué puede acordar el Ayuntamiento de Madrid cuando una incidencia técnica imprevista impide el funcionamiento del registro electrónico?','["La suspensión de todos los procedimientos en curso", "Una ampliación de los plazos no vencidos", "La admisión de documentos por correo electrónico ordinario"]'::jsonb,1,'Art. 41.5 OACAE','Puede determinar una ampliación de los plazos no vencidos, publicando en la Sede Electrónica la incidencia y la ampliación concreta.',null),
('aux-ayto-mad:18-1bb094d5d1','aux-ayto-mad',18,'¿Por qué medios se almacenan los documentos que forman parte del expediente administrativo según la Ordenanza de Atención a la Ciudadanía?','["En papel y, además, en copia electrónica", "En el soporte original en que se presentaron", "Por medios electrónicos, salvo cuando no sea posible"]'::jsonb,2,'Art. 68.2 OACAE','Todos los documentos del expediente se almacenan por medios electrónicos, salvo cuando no sea posible.',null),
('aux-ayto-mad:18-2a8ffd1a9d','aux-ayto-mad',18,'¿Por qué normativa se rige el acceso de las personas a los archivos electrónicos del Ayuntamiento de Madrid?','["Por la Ley de Archivos de la Comunidad de Madrid", "Por el Reglamento Orgánico del Gobierno y de la Administración", "Por la Ordenanza de Transparencia de la Ciudad de Madrid"]'::jsonb,2,'Art. 70.1 OACAE','El acceso de las personas a los archivos electrónicos se rige por la Ordenanza de Transparencia de la Ciudad de Madrid y demás normativa de transparencia.',null),
('aux-ayto-mad:19-bf787cd347','aux-ayto-mad',19,'Las Administraciones deben asistir en el uso de medios electrónicos a:','["Los empleados públicos, para los trámites relacionados con su condición de tales", "Las personas físicas que no estén obligadas a relacionarse electrónicamente", "Las entidades sin personalidad jurídica que carezcan de medios electrónicos propios"]'::jsonb,1,'Art. 12.2 Ley 39/2015','Deben asistir a las personas físicas no obligadas, especialmente en identificación y firma, presentación de solicitudes y obtención de copias auténticas.',null),
('aux-ayto-mad:19-a4ca763cc9','aux-ayto-mad',19,'Las personas físicas, ¿pueden elegir si se comunican con las Administraciones por medios electrónicos?','["No, siempre deben usar medios electrónicos", "Solo si son mayores de 65 años", "Sí, en todo momento, salvo que estén obligadas"]'::jsonb,2,'Art. 14.1 Ley 39/2015','Pueden elegir en todo momento, salvo que estén obligadas a relacionarse electrónicamente.',null),
('aux-ayto-mad:19-50b358dc55','aux-ayto-mad',19,'¿Cuál de los siguientes NO está obligado, con carácter general, a relacionarse electrónicamente con las Administraciones?','["Una persona jurídica", "Una persona física que actúa en su propio nombre", "Un empleado público en trámites por razón de su condición"]'::jsonb,1,'Art. 14.2 Ley 39/2015','Están obligados las personas jurídicas, las entidades sin personalidad, los profesionales con colegiación obligatoria, los representantes de obligados y los empleados públicos en esos trámites.',null),
('aux-ayto-mad:19-febb9a846b','aux-ayto-mad',19,'Las personas tienen derecho a comunicarse con las Administraciones a través de:','["Los perfiles oficiales en redes sociales", "Un Punto de Acceso General electrónico", "Un número de WhatsApp oficial de cada organismo"]'::jsonb,1,'Art. 13 a) Ley 39/2015','Tienen derecho a comunicarse a través de un Punto de Acceso General electrónico de la Administración.',null),
('aux-ayto-mad:19-261b30a503','aux-ayto-mad',19,'Es un derecho de las personas en sus relaciones con las AAPP según el art. 13:','["Elegir al funcionario que tramite su expediente", "Obtener una resolución favorable si la Administración incumple el plazo máximo para resolver", "Ser tratados con respeto y deferencia por las autoridades y empleados públicos"]'::jsonb,2,'Art. 13 e) Ley 39/2015','Otros: comunicarse por el Punto de Acceso General electrónico, ser asistidos en el uso de medios electrónicos, usar lenguas cooficiales, acceso a información pública…',null),
('aux-ayto-mad:19-2d78b10ba0','aux-ayto-mad',19,'Si un interesado no obligado a relacionarse electrónicamente carece de los medios necesarios, su firma electrónica puede realizarla:','["Un funcionario habilitado, pero solo en los procedimientos que se inician de oficio", "Cualquier empleado público de la oficina, sin necesidad de consentimiento expreso del interesado", "Un funcionario habilitado, si el interesado se identifica ante él y presta su consentimiento expreso"]'::jsonb,2,'Art. 12.2 Ley 39/2015','El funcionario firma con su propio sistema; el interesado debe identificarse y prestar consentimiento expreso, del que queda constancia.',null),
('aux-ayto-mad:19-0801b1b71d','aux-ayto-mad',19,'Los funcionarios habilitados para la identificación o firma de los interesados que no disponen de medios electrónicos constan en:','["El registro electrónico de apoderamientos de la Administración correspondiente", "Un registro u otro sistema equivalente que cada Administración mantiene actualizado", "Un listado único estatal publicado en la sede electrónica del Ministerio para la Transformación Digital y de la Función Pública"]'::jsonb,1,'Art. 12.3 Ley 39/2015','La AGE, las CCAA y las Entidades Locales mantienen actualizado un registro u otro sistema equivalente de funcionarios habilitados.',null),
('aux-ayto-mad:19-ec2dff1e0b','aux-ayto-mad',19,'La obligación de relacionarse electrónicamente con la Administración para ciertos colectivos de personas físicas puede establecerse:','["Por resolución del órgano instructor en cada procedimiento concreto", "Reglamentariamente, si queda acreditado que tienen acceso y disponibilidad de los medios electrónicos", "Reglamentariamente, para cualquier persona física mayor de edad"]'::jsonb,1,'Art. 14.3 Ley 39/2015','Puede imponerse por reglamento a colectivos que, por capacidad económica, técnica o dedicación profesional, tengan acceso a esos medios.',null),
('aux-ayto-mad:19-5de517edae','aux-ayto-mad',19,'Según el artículo 13 de la Ley 39/2015, es un derecho de las personas en sus relaciones con las Administraciones Públicas:','["Ser tratadas con respeto y deferencia por las autoridades y empleados públicos, que habrán de facilitarles el ejercicio de sus derechos", "Exigir que se les atienda fuera del horario de atención al público", "Obtener siempre una resolución favorable cuando cumplan los requisitos formales"]'::jsonb,0,'Art. 13 e) Ley 39/2015','El artículo 13 recoge también, entre otros, el derecho a ser asistidas en el uso de medios electrónicos.',null),
('aux-ayto-mad:19-9631a48174','aux-ayto-mad',19,'¿Qué registro deben mantener las Administraciones de los funcionarios habilitados para expedir copias auténticas y asistir en la presentación electrónica?','["Un registro de convenios suscritos con otras Administraciones públicas", "Un registro o sistema equivalente de funcionarios habilitados", "Un registro de órganos colegiados y de sus miembros titulares y suplentes"]'::jsonb,1,'Art. 12.3 Ley 39/2015','El registro electrónico de apoderamientos recoge las representaciones otorgadas por los interesados.',null),
('aux-ayto-mad:19-96838a01e5','aux-ayto-mad',19,'¿Cuál de los siguientes está obligado a relacionarse electrónicamente con las Administraciones según el artículo 14.2 de la Ley 39/2015?','["Las personas físicas mayores de 65 años", "Las personas jurídicas", "Los autónomos sin colegiación obligatoria"]'::jsonb,1,'Art. 14.2 Ley 39/2015','También las entidades sin personalidad jurídica, los profesionales de colegiación obligatoria en el ejercicio de su actividad, sus representantes y los empleados públicos en los trámites por su condición de tales.',null),
('aux-ayto-mad:19-03e1678d5f','aux-ayto-mad',19,'Según la Ley 39/2015, si el interesado no dispone de los medios electrónicos necesarios, su identificación o firma electrónica en el procedimiento puede ser válidamente realizada por:','["Un funcionario público habilitado, mediante el uso del sistema de firma electrónica del que esté dotado", "El representante sindical del interesado", "Un notario de libre elección del interesado, que deberá dar fe del acto realizado y de la identidad del firmante"]'::jsonb,0,'Art. 12.2 Ley 39/2015','El interesado debe identificarse ante el funcionario y prestar su consentimiento expreso, que debe quedar constancia.',null),
('aux-ayto-mad:19-efca780915','aux-ayto-mad',19,'¿Qué servicio integra la atención presencial, telefónica y telemática del Ayuntamiento de Madrid?','["Madrid Contigo", "El Punto de Acceso General", "Línea Madrid"]'::jsonb,2,'Art. 14.1 OACAE','Línea Madrid se configura como el servicio integrador de la atención presencial, telefónica y telemática.',null),
('aux-ayto-mad:19-30d2022c4d','aux-ayto-mad',19,'¿Cuál es el canal telefónico de atención a la ciudadanía de Línea Madrid?','["El 010", "El 060", "El 012"]'::jsonb,0,'Art. 16.1 OACAE','El teléfono 010 es el canal telefónico de atención a la ciudadanía de Línea Madrid.',null),
('aux-ayto-mad:19-5c2d929653','aux-ayto-mad',19,'¿En qué horario está disponible el teléfono 010 del Ayuntamiento de Madrid?','["24 horas los días laborables", "De 8:00 a 22:00 todos los días del año", "24 horas todos los días del año"]'::jsonb,2,'Art. 16.4 OACAE','El 010 está disponible en horario ininterrumpido, 24 horas todos los días del año.',null),
('aux-ayto-mad:19-d31408d26a','aux-ayto-mad',19,'¿Qué coste tienen los servicios que se prestan a través del teléfono 010?','["Tienen el precio público que fije la Junta de Gobierno", "Son gratuitos y la llamada al 010 no tiene coste", "Son gratuitos, pero la llamada se cobra a tarifa local"]'::jsonb,1,'Art. 16.5 OACAE','Los servicios del 010 son gratuitos y la llamada directa al 010 no supone coste alguno en la factura de quien llama.',null),
('aux-ayto-mad:19-1467fce5c9','aux-ayto-mad',19,'¿Qué canal constituyen las Oficinas de Atención a la Ciudadanía de Línea Madrid?','["El canal presencial", "El canal telemático", "El canal especializado"]'::jsonb,0,'Art. 15.1 OACAE','Las Oficinas de Atención a la Ciudadanía constituyen el canal presencial de Línea Madrid.',null),
('aux-ayto-mad:19-4f565ec285','aux-ayto-mad',19,'¿Dónde se ubican, en principio, las Oficinas de Atención a la Ciudadanía de Línea Madrid?','["En los centros culturales de cada barrio", "En las sedes de las Áreas de Gobierno", "En las dependencias de los distritos"]'::jsonb,2,'Art. 15.2 OACAE','Existirán Oficinas de Atención a la Ciudadanía en las dependencias de los distritos o, si no es posible, en otros locales.',null),
('aux-ayto-mad:19-d787d75841','aux-ayto-mad',19,'¿Qué horario tienen las Oficinas de Atención a la Ciudadanía de Línea Madrid?','["Un horario fijo de mañana y franjas de horario de tarde", "Un horario ininterrumpido de 8:00 a 20:00", "El mismo horario que el teléfono 010"]'::jsonb,0,'Art. 15.3 OACAE','Tienen un horario fijo de atención en horario de mañana y franjas de horario de tarde.',null),
('aux-ayto-mad:19-00e232d35c','aux-ayto-mad',19,'¿A quién se facilita obligatoriamente la información administrativa general del Ayuntamiento de Madrid?','["Solo a quienes acrediten la condición de interesados", "Solo a los vecinos empadronados en Madrid", "A cualquier persona que la solicite"]'::jsonb,2,'Art. 12.1 a) OACAE','La información general se facilita obligatoriamente a cualquier persona que la solicite, sin exigir la condición de interesado.',null),
('aux-ayto-mad:19-3a6a5c9e95','aux-ayto-mad',19,'¿Qué efectos tiene la información facilitada por el sistema de atención a la ciudadanía?','["Interrumpe los plazos de prescripción", "Vincula al órgano que deba resolver el procedimiento", "No origina derechos ni expectativas de derecho"]'::jsonb,2,'Art. 13.1 OACAE','Las informaciones no originan derechos ni expectativas de derecho y no pueden invocarse para interrumpir o suspender plazos (art. 13.2).',null),
('aux-ayto-mad:19-e84d3fc360','aux-ayto-mad',19,'¿Cuál es el portal institucional del Ayuntamiento de Madrid?','["madrid.es", "decide.madrid.es", "sede.madrid.es"]'::jsonb,0,'Art. 17.1 OACAE','La web «madrid.es» es el portal institucional; «sede.madrid.es» es la Sede Electrónica.',null),
('aux-ayto-mad:19-26fba2cf9c','aux-ayto-mad',19,'¿Con qué documento deben contar las oficinas de atención especializada del Ayuntamiento de Madrid?','["Con un reglamento interno aprobado por el Pleno", "Con una carta de servicios", "Con un plan anual de calidad aprobado por el alcalde"]'::jsonb,1,'Art. 19.2 OACAE','Las oficinas de atención especializada deben contar con una carta de servicios con sus servicios, compromisos de calidad y derechos de los usuarios.',null),
('aux-ayto-mad:19-3dd26bf7f1','aux-ayto-mad',19,'¿Cuál de estas funciones no corresponde a las Oficinas de Atención a la Ciudadanía de Línea Madrid?','["Resolver los recursos contra los actos de los distritos", "Actuar como oficinas de asistencia en materia de registro", "Registrar y tramitar sugerencias, reclamaciones y felicitaciones"]'::jsonb,0,'Art. 15.1 OACAE','Entre sus funciones están orientar e informar, actuar como oficinas de registro, registrar sugerencias y reclamaciones y realizar gestiones; no resuelven recursos.',null),
('aux-ayto-mad:19-945338f92d','aux-ayto-mad',19,'¿Qué identidad tiene la atención a la ciudadanía en el Ayuntamiento de Madrid?','["Una identidad distinta para cada canal de atención", "Una identidad corporativa única y homogénea", "Una identidad propia en cada distrito"]'::jsonb,1,'Art. 11.3 OACAE','La atención a la ciudadanía tendrá una identidad corporativa única y homogénea.',null),
('aux-ayto-mad:19-33be9d3dd6','aux-ayto-mad',19,'¿Cuál es la Sede Electrónica respecto del punto de acceso general electrónico de la administración municipal de Madrid?','["Es un canal complementario del punto de acceso general", "Solo es accesible desde el punto de acceso general del Estado", "Es el punto de acceso general electrónico del Ayuntamiento"]'::jsonb,2,'Art. 33.7 OACAE','La Sede Electrónica se configura como el punto de acceso general electrónico de la administración del Ayuntamiento de Madrid.',null),
('aux-ayto-mad:20-1fa419635d','aux-ayto-mad',20,'La Comisión especial de Sugerencias y Reclamaciones de los municipios de gran población está formada por:','["Un concejal de cada grupo político y el Secretario General del Pleno", "Representantes de todos los grupos que integren el Pleno, de forma proporcional", "Representantes de las asociaciones vecinales más representativas de la ciudad"]'::jsonb,1,'Art. 132.2 LBRL','Está formada por representantes de todos los grupos del Pleno en proporción a sus miembros, y da cuenta al Pleno mediante un informe anual.',null),
('aux-ayto-mad:20-f800624c4b','aux-ayto-mad',20,'El órgano especializado para la defensa de los derechos de los vecinos ante la Administración municipal deberá dar cuenta al Pleno de su actividad mediante:','["Un informe trimestral", "Un informe anual, sin perjuicio de informes extraordinarios", "Una comparecencia semestral ante la Comisión de Vecinos"]'::jsonb,1,'Art. 27.2 Ley 22/2006','Debe dar cuenta al Pleno mediante un informe anual de las quejas y deficiencias observadas, y puede hacer informes extraordinarios por gravedad o urgencia.',null),
('aux-ayto-mad:20-ddda6e0e29','aux-ayto-mad',20,'Según la Ley 22/2006, la creación de un órgano para la defensa de los derechos de los vecinos es:','["Potestativa para el Pleno", "Obligatoria para el Pleno", "Competencia de la Junta de Gobierno"]'::jsonb,0,'Art. 27.1 Ley 22/2006','El art. 27.1 dice que el Pleno podrá crear este órgano, cuyo funcionamiento se regulará en normas de carácter orgánico.',null),
('aux-ayto-mad:20-9aa4984dcd','aux-ayto-mad',20,'¿Quiénes tienen derecho a presentar sugerencias, reclamaciones y felicitaciones sobre los servicios del Ayuntamiento de Madrid?','["Todas las personas físicas y jurídicas", "Solo las personas físicas mayores de edad", "Solo las personas empadronadas en Madrid"]'::jsonb,0,'Art. 22.1 OACAE','Todas las personas físicas y jurídicas tienen derecho a presentar sugerencias, reclamaciones y felicitaciones.',null),
('aux-ayto-mad:20-f9d89eb373','aux-ayto-mad',20,'¿Están sujetas las sugerencias, reclamaciones y felicitaciones al procedimiento administrativo común?','["No, no están sujetas a él", "Sí, como solicitudes de iniciación a instancia de parte", "Solo las reclamaciones de carácter tributario"]'::jsonb,0,'Art. 22.2 OACAE','Las sugerencias, reclamaciones y felicitaciones no están sujetas al procedimiento administrativo común.',null),
('aux-ayto-mad:20-c25aa68cd9','aux-ayto-mad',20,'¿Qué dos modalidades de sugerencias, reclamaciones y felicitaciones distingue la Ordenanza de Atención a la Ciudadanía?','["De carácter general y de carácter tributario", "Individuales y colectivas", "Presenciales y electrónicas"]'::jsonb,0,'Art. 23 OACAE','Pueden ser de carácter general o de carácter tributario, según se refieran o no a procedimientos tributarios.',null),
('aux-ayto-mad:20-44fff3963f','aux-ayto-mad',20,'¿A través de qué canal se presentan preferentemente las sugerencias, reclamaciones y felicitaciones?','["A través del portal institucional «madrid.es»", "Por el teléfono 010", "En las Oficinas de Atención a la Ciudadanía"]'::jsonb,0,'Art. 24.1 OACAE','Se pueden presentar por los distintos canales, preferentemente a través del portal institucional «madrid.es».',null),
('aux-ayto-mad:20-9ea4e67682','aux-ayto-mad',20,'¿Cuál es el plazo máximo para contestar una sugerencia o reclamación en el Ayuntamiento de Madrid?','["Dos meses desde su entrada", "Tres meses desde su entrada", "Un mes desde su entrada"]'::jsonb,0,'Art. 28.3 OACAE','El plazo de contestación no puede ser superior, en ningún caso, a dos meses desde la entrada en el Ayuntamiento.',null),
('aux-ayto-mad:20-5493aff01c','aux-ayto-mad',20,'¿Cabe recurso contra la respuesta a una sugerencia o reclamación?','["No cabe recurso alguno", "Cabe recurso potestativo de reposición", "Cabe recurso de alzada ante el alcalde"]'::jsonb,0,'Art. 25.3 OACAE','Contra su respuesta no cabe recurso alguno, sin perjuicio de que los motivos puedan exponerse en los recursos del procedimiento relacionado.',null),
('aux-ayto-mad:20-4c91aa9777','aux-ayto-mad',20,'¿Adquiere quien presenta una reclamación la condición de interesado en el procedimiento al que se refiere?','["No, en ningún caso", "Solo si la reclamación tiene carácter tributario", "Sí, desde que la reclamación es admitida"]'::jsonb,0,'Art. 25.4 OACAE','Quien presenta una sugerencia o reclamación en ningún caso adquiere la condición legal de interesado ni se abre la vía de recursos.',null),
('aux-ayto-mad:20-c9eb0e86eb','aux-ayto-mad',20,'¿Paraliza la presentación de una reclamación los plazos establecidos en la normativa?','["Sí, suspende los plazos hasta que se responda", "Solo suspende la ejecución del acto reclamado", "No, ni paraliza plazos ni suspende la ejecución del acto"]'::jsonb,2,'Art. 25.1 OACAE','Su presentación no paraliza los plazos ni suspende la ejecución de la resolución o acto al que se refiera.',null),
('aux-ayto-mad:20-713fab1cad','aux-ayto-mad',20,'¿Qué se hace con una felicitación que se refiere expresamente al buen desempeño de un empleado público?','["Se publica en el portal institucional", "Se comunica al órgano de recursos humanos para su expediente personal", "Se archiva sin más trámite"]'::jsonb,1,'Art. 25.5 OACAE','Se comunica al órgano competente en recursos humanos para su incorporación, en su caso, al expediente personal.',null),
('aux-ayto-mad:20-23924bdc97','aux-ayto-mad',20,'Si una persona desiste de su reclamación, ¿puede el Ayuntamiento seguir tramitándola?','["Solo si la reclamación fue presentada por varias personas", "Sí, de oficio por motivos de interés público", "No, el desistimiento termina siempre la tramitación"]'::jsonb,1,'Art. 26.2 OACAE','En caso de desistimiento se da por terminada, pero el Ayuntamiento puede continuar de oficio por motivos de interés público.',null),
('aux-ayto-mad:20-5fade2bf8b','aux-ayto-mad',20,'¿Cuándo puede acumularse la tramitación de reclamaciones presentadas por distintas personas?','["Cuando se presenten el mismo día", "Cuando coincidan en lo sustancial o en su contenido", "Cuando se dirijan al mismo distrito"]'::jsonb,1,'Art. 27.1 OACAE','Pueden acumularse las presentadas por distintas personas que coincidan en lo sustancial con los hechos o sean coincidentes en su contenido.',null),
('aux-ayto-mad:20-ae21e34388','aux-ayto-mad',20,'¿Cuál de estas reclamaciones puede inadmitirse según la Ordenanza de Atención a la Ciudadanía?','["La que reclame responsabilidad patrimonial al Ayuntamiento", "La presentada por una persona jurídica", "La presentada en una Oficina de Atención a la Ciudadanía"]'::jsonb,0,'Art. 29.1 l) OACAE','Entre los supuestos de inadmisión están las que tengan por objeto reclamar responsabilidad patrimonial, las que sean recursos o las del personal sobre su relación de servicio.',null),
('aux-ayto-mad:20-0b4e8c2b71','aux-ayto-mad',20,'¿Pueden inadmitirse las reclamaciones del personal municipal sobre su particular relación de servicio?','["No, deben tramitarse siempre", "Sí, es un supuesto de inadmisión", "Solo si el empleado es personal laboral"]'::jsonb,1,'Art. 29.1 j) OACAE','Las reclamaciones del personal municipal respecto a su particular relación de servicio pueden inadmitirse.',null),
('aux-ayto-mad:20-03e18f415c','aux-ayto-mad',20,'¿Qué órgano puede dar cuenta al Pleno, mediante un informe anual, de las quejas presentadas sobre los servicios municipales?','["La Intervención General", "La Junta de Gobierno", "La Comisión Especial de Sugerencias y Reclamaciones"]'::jsonb,2,'Art. 30 OACAE','La Comisión Especial de Sugerencias y Reclamaciones del art. 136 del Reglamento Orgánico del Pleno puede supervisar la actividad municipal y dar cuenta al Pleno con un informe anual.',null),
('aux-ayto-mad:20-e3089786d6','aux-ayto-mad',20,'Según los criterios de calidad de las respuestas a sugerencias y reclamaciones, ¿cuándo debe responderse?','["Lo más rápido posible, sin agotar el plazo de dos meses", "Al finalizar el plazo de dos meses, tras recabar todos los informes", "En el plazo de diez días hábiles"]'::jsonb,0,'Art. 32 a) OACAE','Uno de los criterios es la respuesta lo más rápida posible, sin necesidad de agotar el plazo de dos meses.',null),
('aux-ayto-mad:20-2de53a76ad','aux-ayto-mad',20,'Cuando en un mismo escrito se formulan varias reclamaciones, ¿cómo se responde?','["Con una única respuesta conjunta", "Con una respuesta individualizada por cada una", "Respondiendo solo a la principal"]'::jsonb,1,'Art. 27.2 OACAE','El órgano puede dividir el escrito y quien lo presentó recibe respuesta individualizada por cada reclamación incluida.',null),
('aux-ayto-mad:20-507a7aff0e','aux-ayto-mad',20,'En los municipios de gran población, para la defensa de los derechos de los vecinos ante la Administración municipal, el Pleno creará:','["Una Comisión especial de Sugerencias y Reclamaciones", "Un Consejo Social de la Ciudad", "Una Oficina del Defensor del Pueblo municipal"]'::jsonb,0,'Art. 132.1 LBRL','El art. 132.1 obliga al Pleno a crear la Comisión especial de Sugerencias y Reclamaciones, cuyo funcionamiento se regula en normas de carácter orgánico.',null),
('aux-ayto-mad:20-f9c5af388d','aux-ayto-mad',20,'El funcionamiento de la Comisión especial de Sugerencias y Reclamaciones de los municipios de gran población se regula en:','["Normas de carácter orgánico", "Un decreto del Alcalde", "Una instrucción de la Junta de Gobierno Local"]'::jsonb,0,'Art. 132.1 LBRL','Según el art. 132.1, su funcionamiento se regulará en normas de carácter orgánico; su regulación tiene naturaleza orgánica (art. 123.1 c).',null),
('aux-ayto-mad:20-228a55d32a','aux-ayto-mad',20,'La Comisión especial de Sugerencias y Reclamaciones deberá dar cuenta al Pleno de las quejas presentadas y de las deficiencias observadas mediante:','["Un informe anual, sin perjuicio de informes extraordinarios por gravedad o urgencia", "Un informe trimestral a la Junta de Gobierno", "Una memoria al final del mandato"]'::jsonb,0,'Art. 132.3 LBRL','Según el art. 132.3, da cuenta mediante un informe anual, con especificación de las sugerencias o recomendaciones no admitidas, y puede hacer informes extraordinarios.',null),
('aux-ayto-mad:20-d125a75913','aux-ayto-mad',20,'Para el desarrollo de las funciones de la Comisión especial de Sugerencias y Reclamaciones:','["Solo están obligados a colaborar los órganos directivos", "Todos los órganos de Gobierno y de la Administración municipal están obligados a colaborar con ella", "La colaboración de los órganos municipales es voluntaria"]'::jsonb,1,'Art. 132.4 LBRL','Así lo establece el art. 132.4.',null),
('aux-ayto-mad:20-f0fb0829b2','aux-ayto-mad',20,'En el régimen común, la Comisión Especial de Sugerencias y Reclamaciones existe, además de en los municipios de gran población, en aquellos en que:','["Lo pida el 10 % de los vecinos", "Lo autorice la Comunidad Autónoma a propuesta del Alcalde", "El Pleno así lo acuerde por mayoría absoluta del número legal de miembros o lo disponga su Reglamento orgánico"]'::jsonb,2,'Art. 20.1 d) LBRL','El art. 20.1 d) prevé su existencia en los municipios del título X y en los demás cuando lo acuerde el Pleno por mayoría absoluta o lo disponga el Reglamento orgánico.',null),
('aux-ayto-mad:20-c1d41e4423','aux-ayto-mad',20,'La Comisión especial de Sugerencias y Reclamaciones podrá, según la Ley 7/1985:','["Anular los actos administrativos que considere ilegales", "Imponer sanciones a los empleados municipales", "Supervisar la actividad de la Administración municipal"]'::jsonb,2,'Art. 132.3 LBRL','Según el art. 132.3, podrá supervisar la actividad de la Administración municipal.',null),
