('aux-ayto-mad:21-ea6e1416e4','aux-ayto-mad',21,'En Word, la vista que muestra el documento tal como se imprimirá, con márgenes y encabezados, es:','["Esquema con encabezados y márgenes", "Diseño de impresión", "Diseño web con márgenes"]'::jsonb,1,'Word · Vista','Es la vista predeterminada.',null),
