('aux-ayto-mad:22-2d958ff740','aux-ayto-mad',22,'¿Qué función de Excel cuenta las celdas de un rango que cumplen un criterio?','["CONTARA", "CONTAR.SI", "CONTAR.BLANCO"]'::jsonb,1,'Excel · Funciones','Ejemplo: =CONTAR.SI(A1:A10;">5").',null),
